<body>
  <div class="shell" data-harness-ready="true">
    <header>
      <div class="brand"><span class="mark"><span>↘</span></span> Tuck</div>
      <div class="prototype-label">First-flow prototype</div>
    </header>

    <main>
      <div class="eyebrow">Your bookmark home</div>
      <h1>Keep the good parts of the web.</h1>
      <p class="intro">Save useful links here, so the things worth remembering don't disappear into open tabs.</p>

      <form class="save-card" id="save-form" novalidate>
        <div class="form-row">
          <div>
            <label for="url">Web address</label>
            <input id="url" name="url" type="url" placeholder="https://example.com/article" autocomplete="url" required>
          </div>
          <div>
            <label for="title">Title <span style="font-weight: 400; color: var(--muted)">(optional)</span></label>
            <input id="title" name="title" type="text" placeholder="What do you want to remember?" autocomplete="off">
          </div>
        </div>
        <div class="error" id="error" role="alert"></div>
        <div class="metadata-preview" id="metadata-preview" aria-live="polite" hidden>
          <div class="metadata-icon" id="metadata-icon">E</div>
          <div class="metadata-copy">
            <div class="metadata-status" id="metadata-status">Looking up page details…</div>
            <div class="metadata-description" id="metadata-description"></div>
          </div>
        </div>
        <div class="actions">
          <span class="hint">Your link will appear in the collection below.</span>
          <button class="save-button" type="submit">Save bookmark</button>
        </div>
      </form>

      <section class="collection" aria-labelledby="collection-title">
        <div class="collection-head">
          <h2 id="collection-title">Saved links</h2>
          <span class="count" id="count">0 bookmarks</span>
        </div>
        <div id="bookmark-list">
          <div class="empty" id="empty"><strong>Nothing saved yet</strong>Your first useful link starts here.</div>
        </div>
      </section>
    </main>
  </div>

  <script>
    const form = document.querySelector('#save-form');
    const urlInput = document.querySelector('#url');
    const titleInput = document.querySelector('#title');
    const list = document.querySelector('#bookmark-list');
    const error = document.querySelector('#error');
    const count = document.querySelector('#count');
    const preview = document.querySelector('#metadata-preview');
    const previewIcon = document.querySelector('#metadata-icon');
    const previewStatus = document.querySelector('#metadata-status');
    const previewDescription = document.querySelector('#metadata-description');
    let total = 0;
    let lookupTimer;
    let metadata = null;
    let titleWasEdited = false;

    titleInput.addEventListener('input', () => {
      titleWasEdited = true;
    });

    urlInput.addEventListener('input', () => {
      clearTimeout(lookupTimer);
      metadata = null;
      titleWasEdited = false;
      preview.hidden = true;
      error.textContent = '';

      let parsed;
      try {
        parsed = new URL(urlInput.value.trim());
        if (!['http:', 'https:'].includes(parsed.protocol)) return;
      } catch {
        return;
      }

      preview.hidden = false;
      preview.classList.add('loading');
      previewStatus.textContent = 'Looking up page details…';
      previewDescription.textContent = 'Reading the page title, description and site icon';

      lookupTimer = setTimeout(() => {
        const isExample = parsed.hostname.replace(/^www\./, '') === 'example.com';
        metadata = isExample
          ? {
              title: 'Example Domain',
              description: 'A reserved domain used in examples and documentation.',
              icon: 'E'
            }
          : {
              title: parsed.hostname.replace(/^www\./, ''),
              description: `A saved page from ${parsed.hostname.replace(/^www\./, '')}`,
              icon: parsed.hostname.replace(/^www\./, '').charAt(0).toUpperCase()
            };

        if (!titleWasEdited) titleInput.value = metadata.title;
        preview.classList.remove('loading');
        previewIcon.textContent = metadata.icon;
        previewStatus.textContent = 'Page details found — you can edit the title';
        previewDescription.textContent = metadata.description;
      }, 650);
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      error.textContent = '';

      let parsed;
      try {
        parsed = new URL(urlInput.value.trim());
        if (!['http:', 'https:'].includes(parsed.protocol)) throw new Error('Unsupported address');
      } catch {
        error.textContent = 'Enter a complete web address, such as https://example.com';
        urlInput.focus();
        return;
      }

      document.querySelector('#empty')?.remove();
      total += 1;

