@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Newsreader:ital,opsz,wght@0,6..72,500;1,6..72,500&display=swap');

:root {
  color-scheme: light;
  --ink: #17201b;
  --soft-ink: #526057;
  --muted: #7b857e;
  --canvas: #f3f1eb;
  --surface: #fffefa;
  --line: #dcded8;
  --leaf: #1d6749;
  --leaf-deep: #124b35;
  --leaf-soft: #dcece2;
  --gold: #d9a441;
  --danger: #a83d35;
  --danger-soft: #f9e9e6;
  --shadow: 0 24px 70px rgba(39, 49, 42, .09);
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  color: var(--ink);
  background: var(--canvas);
  font-family: "DM Sans", ui-sans-serif, system-ui, sans-serif;
}

button, input { font: inherit; }
button { color: inherit; }

.page-glow {
  position: fixed;
  z-index: -1;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

.page-glow::before,
.page-glow::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  filter: blur(2px);
}

.page-glow::before {
  width: 560px;
  height: 560px;
  right: -170px;
  top: -250px;
  background: radial-gradient(circle, rgba(181, 216, 192, .7), rgba(181, 216, 192, 0) 70%);
}

.page-glow::after {
  width: 460px;
  height: 460px;
  left: -250px;
  top: 520px;
  background: radial-gradient(circle, rgba(235, 210, 158, .36), rgba(235, 210, 158, 0) 70%);
}

.app-shell {
  width: min(960px, calc(100% - 40px));
  margin: 0 auto;
  padding: 26px 0 90px;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 74px;
