.undo-toast {
  position: fixed;
  z-index: 20;
  right: 24px;
  bottom: 24px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 24px;
  width: min(360px, calc(100% - 48px));
  padding: 15px 17px 12px;
  overflow: hidden;
  color: white;
  background: #1e2922;
  border-radius: 13px;
  box-shadow: 0 18px 45px rgba(24, 33, 27, .28);
